grades = {}
try:
with open("marks.txt") as f:
for line in f:
name, m = line.strip().split(",")
grades[name] = int(m)
except FileNotFoundError:
print("Error: marks.txt is missing")
else:
with open("grades.txt", "w") as g:
for name, m in grades.items():
grade = "A" if m >= 80 else "B"
g.write(name + ": " + grade + "\n")
